UPDATE material_translations SET body='{"captions":["Zonele de vegetație ale Terrei – harta de ansamblu","Pădurile ecuatoriale și musonice – răspândirea pe glob","Pădurea ecuatorială – vegetație veșnic verde, etajată pe mai multe niveluri. Climograma zonei (Iquitos): temperatură medie anuală 26,3 °C, amplitudine termică 1 °C, 2088 mm de precipitații pe an.","Fauna pădurii ecuatoriale: jaguarul, urangutanul, gorila, tucanul, leneșul și papagalul ara","Savana – răspândirea pe glob","Savana – ierburi înalte cu acacii izolate, verzi în sezonul ploios și uscate în cel secetos. Climograma zonei (Veracruz): temperatură medie anuală 28,3 °C, amplitudine termică 8 °C, 998 mm de precipitații pe an.","Fauna savanei: leul, elefantul african, girafa, zebra, ghepardul și rinocerul alb","Pustiurile și semipustiurile tropicale – răspândirea pe glob","Pustiul tropical – dune și oază cu curmali, vegetație doar acolo unde există apă. Climograma zonei (Kalgoorlie): temperatură medie anuală 24,1 °C, amplitudine termică 23 °C, 15 mm de precipitații pe an.","Fauna pustiului tropical: dromaderul, vulpea fenec, suricata, scorpionul, antilopa oryx și șarpele cu clopoței","Zona subtropicală – maquis-ul mediteranean și pădurile subtropicale umede, răspândirea pe glob","Maquis-ul mediteranean – tufișuri veșnic verzi, cu frunze mici și tari, adaptate la vara secetoasă. Climograma zonei (Atena): temperatură medie anuală 18,2 °C, amplitudine termică 19 °C, 430 mm de precipitații pe an.","Pădurea subtropicală umedă – arbori acoperiți de ferigi și epifite, verzi tot anul. Climograma zonei (Taipei): temperatură medie anuală 22,8 °C, amplitudine termică 14 °C, 2255 mm de precipitații pe an.","Fauna mediteraneană: râsul iberic, mistrețul, muflonul, broasca țestoasă de uscat, vipera și macacul de Gibraltar","Fauna pădurilor subtropicale umede: ursul panda mare, tigrul, panda roșu, leopardul nebulos, păunul și macacii","Pădurea de foioase – răspândirea pe glob","Pădurea de foioase – arbori care își pierd frunzele iarna. Climograma zonei (Londra): temperatură medie anuală 10,8 °C, amplitudine termică 13 °C, 617 mm de precipitații pe an.","Fauna pădurii de foioase: cerbul, ursul brun, lupul, vulpea, mistrețul și căprioara","Stepele, preriile și pustiurile reci – răspândirea pe glob","Stepa – întindere de ierburi, fără arbori, cu rădăcini adânci. Climograma zonei (Aktiubinsk): temperatură medie anuală 5,3 °C, amplitudine termică 36 °C, 290 mm de precipitații pe an.","Pustiul rece – ierburi rare și tufe pipernicite la poalele munților. Climograma zonei (Ulaanbaatar): temperatură medie anuală 0,4 °C, amplitudine termică 41 °C, 209 mm de precipitații pe an.","Fauna stepei, preriei și pampasului: bizonul american, nandul, hârciogul, coiotul, iepurele de câmp și antilopa saiga","Fauna pustiurilor alpine: antilopa chiru, kiangul, iacul sălbatic, puma, vizcacha și leopardul de zăpadă","Pădurea de conifere (taigaua) – răspândirea pe glob","Taigaua – pădure de molizi, brazi și pini, cu frunze-ace care rezistă la ger. Climograma zonei (Iakutsk): temperatură medie anuală -9,1 °C, amplitudine termică 59 °C, 203 mm de precipitații pe an.","Fauna taigalei: elanul, ursul brun, gulo (jderul-ursuleț), râsul, veverița și cocoșul de munte","Tundra și deșerturile polare – răspândirea pe glob","Tundra – mușchi, licheni și tufe pitice pe sol permanent înghețat în adânc. Climograma zonei (Inuvik): temperatură medie anuală -7,2 °C, amplitudine termică 45 °C, 238 mm de precipitații pe an.","Deșertul polar – gheață și stâncă golașă, aproape lipsit de vegetație. Climograma zonei (McMurdo): temperatură medie anuală -16,8 °C, amplitudine termică 29 °C, 83 mm de precipitații pe an.","Fauna tundrei: ursul polar, vulpea polară, bufnița de zăpadă, renul, boul moscat și lemingul","Fauna zonelor polare: ursul polar și morsa în Arctica, pinguinul imperial în Antarctica, foca, beluga și iepurele arctic"]}' WHERE material_id='07c35944-e7cd-457d-a1cb-6c65528b7dbf' AND locale='ro';
UPDATE materials SET updated_at=1787571085471 WHERE id='07c35944-e7cd-457d-a1cb-6c65528b7dbf';
